import { McpServer } from "@modelcontextprotocol/sdk/server/mcp";
import dns from "node:dns";
import http from "node:http";
import https from "node:https";
import net from "node:net";
import path from "node:path";
import { z } from "zod";
import { documentUrl } from "../api/documentLinks";
import { PaperlessAPI } from "../api/PaperlessAPI";
import { MAX_FILE_SIZE_BYTES } from "./documents";
import { withErrorHandling } from "./utils/middlewares";

// Agents cannot use post_document: its base64 `file` has to be generated by the
// model byte for byte, and `file_path` reads the server's own filesystem. This
// tool takes a URL instead and the server fetches the bytes.
//
// SSRF: the server can reach whatever networks it runs on. Every connection is
// checked at connect time against the resolved address (so DNS rebinding between
// check and connect cannot slip past), every redirect hop is re-checked, and only
// globally routable unicast addresses are allowed.

const FETCH_TIMEOUT_MS = 180 * 1000;
const MAX_REDIRECTS = 5;
export const MAX_WAIT_SECONDS = 120;
const POLL_INTERVAL_MS = 2000;
// Some publishers (Springer, several university repositories) refuse clients
// that do not look like a browser.
const USER_AGENT =
  "Mozilla/5.0 (compatible; paperless-mcp url-upload; +https://docs.paperless-ngx.com)";

// IPv4-mapped IPv6 (::ffff:a.b.c.d) is matched against the IPv4 rules by BlockList itself.
const BLOCKED = new net.BlockList();
for (const [addr, prefix] of [
  ["0.0.0.0", 8],
  ["10.0.0.0", 8],
  ["100.64.0.0", 10], // CGNAT, also Tailscale
  ["127.0.0.0", 8],
  ["169.254.0.0", 16], // link-local, incl. cloud metadata
  ["172.16.0.0", 12], // RFC 1918, incl. Docker's default networks
  ["192.0.0.0", 24],
  ["192.0.2.0", 24],
  ["192.88.99.0", 24],
  ["192.168.0.0", 16],
  ["198.18.0.0", 15],
  ["198.51.100.0", 24],
  ["203.0.113.0", 24],
  ["224.0.0.0", 4],
  ["240.0.0.0", 4],
] as const) {
  BLOCKED.addSubnet(addr, prefix, "ipv4");
}
for (const [addr, prefix] of [
  ["2001::", 32], // Teredo: embeds an arbitrary IPv4
  ["2001:db8::", 32],
  ["2002::", 16], // 6to4: embeds an arbitrary IPv4
] as const) {
  BLOCKED.addSubnet(addr, prefix, "ipv6");
}
// IPv6 is allow-listed: only 2000::/3 is global unicast, which excludes ::1, ::,
// fc00::/7, fe80::/10, ff00::/8, 64:ff9b::/96 and the mapped range in one rule.
const GLOBAL_V6 = new net.BlockList();
GLOBAL_V6.addSubnet("2000::", 3, "ipv6");

export function isPublicAddress(address: string, family?: number | string): boolean {
  const fam =
    family === 6 || family === "IPv6" || net.isIPv6(address) ? "ipv6" : "ipv4";
  if (fam === "ipv6" && !GLOBAL_V6.check(address, "ipv6")) {
    return false;
  }
  return !BLOCKED.check(address, fam);
}

class BlockedAddressError extends Error {}

// Replaces dns.lookup for every outbound socket. Node's connect path calls it with
// {all: true} when autoSelectFamily is on (the default) and without otherwise, so
// both shapes are answered. Any non-public answer refuses the host rather than
// connecting to whichever record happens to be public.
function guardedLookup(hostname: string, optionsArg: any, callbackArg?: any): void {
  const callback = typeof optionsArg === "function" ? optionsArg : callbackArg;
  let options: dns.LookupOptions = {};
  if (typeof optionsArg === "number") {
    options = { family: optionsArg };
  } else if (optionsArg && typeof optionsArg === "object") {
    options = optionsArg;
  }
  dns.lookup(hostname, { ...options, all: true }, (err, addresses) => {
    if (err) {
      return callback(err);
    }
    const bad = addresses.find((a) => !isPublicAddress(a.address, a.family));
    if (bad) {
      return callback(
        new BlockedAddressError(
          `Refusing to fetch from ${hostname}: it resolves to ${bad.address}, which is not a public address.`
        )
      );
    }
    if (options.all) {
      return callback(null, addresses);
    }
    return callback(null, addresses[0].address, addresses[0].family);
  });
}

function assertFetchable(url: URL): void {
  if (url.protocol !== "http:" && url.protocol !== "https:") {
    throw new Error(`Only http and https URLs can be fetched, not ${url.protocol}`);
  }
  // Node never calls lookup() for an IP literal.
  const host = url.hostname.replace(/^\[|\]$/g, "");
  if (net.isIP(host) && !isPublicAddress(host)) {
    throw new BlockedAddressError(`Refusing to fetch from ${host}: not a public address.`);
  }
}

interface Fetched {
  status: number;
  body: Buffer;
  contentType: string;
  contentDisposition: string;
  finalUrl: string;
}

type Hop = { location: string } | Omit<Fetched, "finalUrl">;

function tooLarge(bytes: number): Error {
  return new Error(
    `File is larger than the ${Math.round(MAX_FILE_SIZE_BYTES / 1024 / 1024)}MB upload limit ` +
      `(at least ${Math.round(bytes / 1024 / 1024)}MB).`
  );
}

function requestOnce(url: URL, deadline: number): Promise<Hop> {
  return new Promise((resolve, reject) => {
    const remaining = deadline - Date.now();
    if (remaining <= 0) {
      return reject(new Error(`Timed out fetching ${url.href}`));
    }
    const mod = url.protocol === "https:" ? https : http;
    const req = mod.get(url, {
      lookup: guardedLookup as any,
      headers: { "User-Agent": USER_AGENT, Accept: "application/pdf,*/*;q=0.8" },
      // A fresh agent per request: a pooled socket would skip lookup() entirely.
      agent: new mod.Agent({ keepAlive: false }),
    });
    const timer = setTimeout(() => {
      req.destroy(new Error(`Timed out after ${FETCH_TIMEOUT_MS / 1000}s fetching ${url.href}`));
    }, remaining);
    const fail = (err: Error) => {
      clearTimeout(timer);
      reject(err);
    };
    req.on("error", fail);
    req.on("response", (res) => {
      const status = res.statusCode || 0;
      if (status >= 300 && status < 400 && res.headers.location) {
        res.resume();
        clearTimeout(timer);
        return resolve({ location: res.headers.location });
      }
      if (status < 200 || status >= 300) {
        res.resume();
        return fail(new Error(`GET ${url.href} returned HTTP ${status}`));
      }
      const declared = Number(res.headers["content-length"]);
      if (declared > MAX_FILE_SIZE_BYTES) {
        req.destroy();
        return fail(tooLarge(declared));
      }
      const chunks: Buffer[] = [];
      let received = 0;
      res.on("data", (chunk: Buffer) => {
        received += chunk.length;
        if (received > MAX_FILE_SIZE_BYTES) {
          req.destroy(tooLarge(received));
          return;
        }
        chunks.push(chunk);
      });
      res.on("error", fail);
      res.on("end", () => {
        clearTimeout(timer);
        resolve({
          status,
          body: Buffer.concat(chunks, received),
          contentType: String(res.headers["content-type"] || ""),
          contentDisposition: String(res.headers["content-disposition"] || ""),
        });
      });
    });
  });
}

async function fetchDocument(rawUrl: string): Promise<Fetched> {
  let current: URL;
  try {
    current = new URL(rawUrl);
  } catch {
    throw new Error(`Not a valid URL: ${rawUrl}`);
  }
  const deadline = Date.now() + FETCH_TIMEOUT_MS;
  for (let hop = 0; hop <= MAX_REDIRECTS; hop++) {
    assertFetchable(current);
    const res = await requestOnce(current, deadline);
    if ("location" in res) {
      current = new URL(res.location, current);
      continue;
    }
    return { ...res, finalUrl: current.href };
  }
  throw new Error(`Too many redirects (more than ${MAX_REDIRECTS}) fetching ${rawUrl}`);
}

function isPdf(body: Buffer): boolean {
  return body.subarray(0, 1024).includes("%PDF-");
}

// The bytes win over the header: a PDF served as text/html is still a PDF.
export function looksLikeHtml(body: Buffer, contentType: string): boolean {
  if (isPdf(body)) {
    return false;
  }
  if (/^\s*(text\/html|application\/xhtml)/i.test(contentType)) {
    return true;
  }
  const head = body
    .subarray(0, 512)
    .toString("latin1")
    .replace(/^\uFEFF?\s*/, "")
    .toLowerCase();
  return head.startsWith("<!doctype html") || head.startsWith("<html");
}

function filenameFromDisposition(header: string): string | undefined {
  if (!header) {
    return undefined;
  }
  const star = /filename\*\s*=\s*(?:[\w-]+)?'[^']*'([^;]+)/i.exec(header);
  if (star) {
    try {
      return decodeURIComponent(star[1].trim().replace(/^"|"$/g, ""));
    } catch {
      // Fall through to the plain parameter.
    }
  }
  const plain = /filename\s*=\s*("([^"]*)"|[^;]+)/i.exec(header);
  if (plain) {
    return (plain[2] === undefined ? plain[1] : plain[2]).trim();
  }
  return undefined;
}

// Control characters and path separators become "_".
function sanitizeName(name: string): string {
  let out = "";
  for (const ch of name) {
    const code = ch.codePointAt(0)!;
    out += code < 0x20 || code === 0x7f || ch === "/" || ch === "\\" ? "_" : ch;
  }
  return out.trim();
}

// Paperless uses the filename as the title until something better arrives:
// explicit > Content-Disposition > the URL's last path segment. arXiv's
// /pdf/1905.03222 has no extension (and a ".03222" that looks like one), so
// ".pdf" is added from the bytes rather than inferred from the name.
export function deriveFilename(
  explicit: string | undefined,
  contentDisposition: string,
  finalUrl: string,
  body: Buffer
): string {
  let name = explicit || filenameFromDisposition(contentDisposition);
  if (!name) {
    try {
      const segment = new URL(finalUrl).pathname.split("/").filter(Boolean).pop();
      name = segment ? decodeURIComponent(segment) : undefined;
    } catch {
      name = undefined;
    }
  }
  name = sanitizeName(path.basename(String(name || "document")));
  if (!name || name === "." || name === "..") {
    name = "document";
  }
  if (name.length > 200) {
    const ext = path.extname(name);
    name = name.slice(0, 200 - ext.length) + ext;
  }
  if (isPdf(body) && !/\.pdf$/i.test(name)) {
    name += ".pdf";
  }
  return name;
}

export interface TaskSummary {
  task_id?: string;
  status: string;
  result?: unknown;
  outcome?: "created" | "duplicate" | "failed" | "pending";
  document_id?: number | null;
  web_url?: string | null;
  duplicate_of?: { id: number; title: string; web_url: string | null }[];
}

// Accepts both the API v9 and v10 task shapes, so an API version bump degrades to
// missing fields rather than wrong ones.
export function summarizeTask(task: any): TaskSummary {
  if (!task) {
    return { status: "unknown" };
  }
  const status = String(task.status || "unknown").toLowerCase();
  let related: number | null = null;
  if (task.related_document !== null && task.related_document !== undefined) {
    related = Number(task.related_document);
  } else if (Array.isArray(task.related_document_ids) && task.related_document_ids.length) {
    related = Number(task.related_document_ids[0]);
  }
  let result: unknown = null;
  if (task.result !== null && task.result !== undefined) {
    result = task.result;
  } else if (task.result_data !== null && task.result_data !== undefined) {
    result = task.result_data;
  }
  const duplicates: any[] = Array.isArray(task.duplicate_documents)
    ? task.duplicate_documents
    : [];
  const out: TaskSummary = { task_id: task.task_id, status, result };
  if (duplicates.length) {
    out.outcome = "duplicate";
    out.duplicate_of = duplicates.map((d) => ({
      id: d.id,
      title: d.title,
      web_url: documentUrl(d.id),
    }));
  } else if (status === "success") {
    out.outcome = "created";
    out.document_id = related;
    if (related != null) out.web_url = documentUrl(related);
  } else if (status === "failure") {
    out.outcome = "failed";
  } else {
    out.outcome = "pending";
  }
  return out;
}

async function getTask(api: PaperlessAPI, taskId: string): Promise<any> {
  const res = await api.request(`/tasks/?task_id=${encodeURIComponent(taskId)}`);
  if (Array.isArray(res)) {
    return res[0];
  }
  return res && Array.isArray(res.results) ? res.results[0] : undefined;
}

export async function waitForTask(
  api: PaperlessAPI,
  taskId: string,
  waitSeconds: number
): Promise<TaskSummary> {
  const deadline = Date.now() + waitSeconds * 1000;
  for (;;) {
    const task = await getTask(api, taskId);
    const summary = summarizeTask(task || { task_id: taskId, status: "pending" });
    if (summary.outcome !== "pending" || Date.now() + POLL_INTERVAL_MS > deadline) {
      return summary;
    }
    await new Promise((r) => setTimeout(r, POLL_INTERVAL_MS));
  }
}

// post_document returns a document id (when Paperless consumes synchronously) or a
// consume task UUID; turn either into an outcome the caller can act on.
export async function uploadOutcome(
  api: PaperlessAPI,
  response: unknown,
  waitSeconds = 30
): Promise<Record<string, unknown>> {
  if (typeof response === "string" && /^\d+$/.test(response)) {
    const id = Number(response);
    return { outcome: "created", document_id: id, web_url: documentUrl(id) };
  }
  if (typeof response === "string") {
    return waitSeconds > 0
      ? { ...(await waitForTask(api, response, waitSeconds)) }
      : { task_id: response, status: "pending", outcome: "pending" };
  }
  return { status: response };
}

export const UPLOAD_METADATA_SHAPE = {
  title: z.string().optional(),
  created: z.string().optional(),
  correspondent: z.number().optional(),
  document_type: z.number().optional(),
  storage_path: z.number().optional(),
  tags: z.array(z.number()).optional(),
  archive_serial_number: z.number().optional(),
  custom_fields: z.array(z.number()).optional(),
  wait_seconds: z
    .number()
    .min(0)
    .max(MAX_WAIT_SECONDS)
    .optional()
    .describe(
      `How long to wait for Paperless to consume the file before returning (0-${MAX_WAIT_SECONDS}, default 30). 0 returns the task id immediately.`
    ),
};

export function registerUrlUploadTools(server: McpServer, api: PaperlessAPI) {
  server.tool(
    "post_document_from_url",
    "Add a document to Paperless by URL: the server downloads the file itself and uploads it. " +
      "This is the way to add a paper from the web -- post_document's base64 'file' argument " +
      "cannot carry a real PDF, since every byte would have to be written out in the tool call. " +
      "Use the DIRECT file link, not a landing page (e.g. https://arxiv.org/pdf/<id>, not /abs/<id>); " +
      "an HTML response is rejected. Only public http(s) URLs are fetched. " +
      "Set 'title' (or a descriptive 'filename' like 'Author Year - Title.pdf'), otherwise the " +
      "title starts as the URL's filename. By default waits up to 30s for Paperless to finish " +
      "consuming and reports the outcome: 'created' with document_id, 'duplicate' with the existing " +
      "document (re-adding a paper already in the library is rejected, not duplicated), 'failed', or " +
      "'pending' -- check a pending task later with get_task_status. When reporting a created " +
      "or existing paper, include its clickable web_url so the user can open it in Paperless.",
    {
      url: z
        .string()
        .describe("Public http(s) URL of the file itself (PDF, image, office document, ...)."),
      filename: z
        .string()
        .optional()
        .describe(
          "Filename to give the upload. Defaults to the server's Content-Disposition name or the URL's last path segment."
        ),
      ...UPLOAD_METADATA_SHAPE,
    },
    withErrorHandling(async (args) => {
      if (!api) throw new Error("Please configure API connection first");
      const fetched = await fetchDocument(args.url);
      if (fetched.body.length === 0) {
        throw new Error(`${fetched.finalUrl} returned an empty body.`);
      }
      if (looksLikeHtml(fetched.body, fetched.contentType)) {
        throw new Error(
          `${fetched.finalUrl} returned an HTML page, not a document -- usually a landing page, ` +
            "paywall, or error page. Pass the direct link to the file (for arXiv, /pdf/<id> rather than /abs/<id>)."
        );
      }
      const filename = deriveFilename(
        args.filename,
        fetched.contentDisposition,
        fetched.finalUrl,
        fetched.body
      );
      const { url, filename: _fn, wait_seconds, ...metadata } = args;
      const response = await api.postDocument(fetched.body, filename, metadata);
      const result = {
        source_url: url,
        final_url: fetched.finalUrl,
        filename,
        bytes: fetched.body.length,
        content_type: fetched.contentType || null,
        ...(await uploadOutcome(api, response, wait_seconds)),
      };
      return { content: [{ type: "text", text: JSON.stringify(result, null, 2) }] };
    })
  );

  server.tool(
    "get_task_status",
    "Look up a Paperless consume task by the task id an upload returned. outcome is " +
      "'created' (with document_id), 'duplicate' (with the existing document it matched), " +
      "'failed' (see result), or 'pending'. Include the web_url for created or duplicate " +
      "documents in your answer so the user can open them directly.",
    { task_id: z.string().describe("Task UUID returned by an upload.") },
    withErrorHandling(async (args) => {
      if (!api) throw new Error("Please configure API connection first");
      const task = await getTask(api, args.task_id);
      if (!task) {
        throw new Error(`No task with id ${args.task_id}`);
      }
      return {
        content: [{ type: "text", text: JSON.stringify(summarizeTask(task), null, 2) }],
      };
    })
  );
}
